const express = require('express');
const path = require('path');
const fs = require('fs');
const crypto = require('crypto');
const { spawn } = require('child_process');

// PLAN MAISON — serveur autonome : les fichiers web et le script Blender
// sont embarqués dans server.js pour éviter les problèmes d'upload de dossiers.
const APP = __dirname;
const PUBLIC = path.join(APP, 'public');
const BLENDER_DIR = path.join(APP, 'blender');
const RENDERS = path.join(APP, 'renders');
const HTML_B64 = '';
const BLENDER_B64 = '';

fs.mkdirSync(PUBLIC, { recursive: true });
fs.mkdirSync(BLENDER_DIR, { recursive: true });
fs.mkdirSync(RENDERS, { recursive: true });

function bootstrapFiles() {
  const html = Buffer.from(HTML_B64, 'base64');
  const blender = Buffer.from(BLENDER_B64, 'base64');
  const htmlPath = path.join(PUBLIC, 'index.html');
  const blenderPath = path.join(BLENDER_DIR, 'render_plan.py');
  if (!fs.existsSync(htmlPath) || fs.statSync(htmlPath).size !== html.length) fs.writeFileSync(htmlPath, html);
  if (!fs.existsSync(blenderPath) || fs.statSync(blenderPath).size !== blender.length) fs.writeFileSync(blenderPath, blender);
}
bootstrapFiles();

const app = express();
const PORT = process.env.PORT || 3000;
const BLENDER = process.env.BLENDER_BIN || 'blender';
const TIMEOUT = Number(process.env.RENDER_TIMEOUT_MS || 180000);

app.use(express.json({ limit: '2mb' }));
app.use(express.static(PUBLIC));
app.use('/renders', express.static(RENDERS, { maxAge: '1h' }));

app.get('/api/health', (req, res) => res.json({
  ok: true,
  service: 'PLAN MAISON 3D',
  blender: BLENDER,
  autonomous: true
}));

function runBlender(payload, outFile) {
  return new Promise((resolve, reject) => {
    const script = path.join(BLENDER_DIR, 'render_plan.py');
    const args = ['-b', '-P', script, '--', '--payload', JSON.stringify(payload), '--output', outFile];
    const child = spawn(BLENDER, args, { cwd: APP });
    let stderr = '';
    let stdout = '';
    let settled = false;
    const timer = setTimeout(() => {
      if (settled) return;
      settled = true;
      child.kill('SIGKILL');
      reject(new Error('Le rendu 3D a dépassé le délai autorisé.'));
    }, TIMEOUT);
    child.stdout.on('data', d => { stdout += d.toString(); });
    child.stderr.on('data', d => { stderr += d.toString(); });
    child.on('error', err => {
      if (settled) return;
      settled = true; clearTimeout(timer); reject(err);
    });
    child.on('close', code => {
      if (settled) return;
      settled = true; clearTimeout(timer);
      if (code === 0 && fs.existsSync(outFile)) resolve();
      else reject(new Error(`Blender a échoué (code ${code}). ${stderr.slice(-1800)} ${stdout.slice(-800)}`));
    });
  });
}

app.post('/api/render3d', async (req, res) => {
  try {
    const payload = req.body || {};
    const plan = payload.plan;
    if (!plan || !Array.isArray(plan.rooms)) return res.status(400).json({ ok:false, error:'Plan structuré manquant.' });
    if (plan.rooms.length > 80) return res.status(400).json({ ok:false, error:'Plan trop volumineux.' });
    const id = crypto.randomUUID();
    const file = path.join(RENDERS, `${id}.png`);
    await runBlender(payload, file);
    res.json({ ok:true, image_url:`/renders/${id}.png`, id });
  } catch (e) {
    console.error(e);
    res.status(500).json({ ok:false, error:e.message || 'Erreur de rendu 3D' });
  }
});

app.get('*', (req, res) => res.sendFile(path.join(PUBLIC, 'index.html')));
app.listen(PORT, () => console.log(`PLAN MAISON 3D listening on ${PORT}`));
